INSERT INTO `posts` (`id`, `title`, `slug`, `content`, `thumbnail`, `category_id`, `is_published`, `view_count`, `created_at`, `updated_at`, `published_at`) VALUES
(1, 'İMAM HATİP SPOR OYUNLARI 81 İLDE DÜZENLENECEK', 'i-mam-hati-p-spor-oyunlari-81-i-lde-duzenlenecek', '<p>İstanbul’daki imam hatip ortaokulları ve liselerine yönelik her yıl geleneksel olarak düzenlenen İmam Hatip Spor Oyunları Türkiye geneline açılıyor. Bu yıl 16. kez düzenlenecek turnuva kapsamında İstanbul’da 17, Anadolu’da ise 5 ayrı branşta yarışmalar yapılacak. Hedef, her okulun ve her öğrencinin en az bir branşla buluşmasını sağlamak.&nbsp;</p><h3>ÖNDER İmam Hatipliler Derneği çatısı altında faaliyet gösteren Öncü Spor Kulübü tarafından 2009 yılında İstanbul’da başlatılan ve her yıl 5 bin civarında gencin yarıştığı İmam Hatip Spor Oyunları, tüm gençlere ulaşan ulusal bir harekete dönüşüyor. 81 ilde düzenlenecek turnuvalarda yüz binlerce gencin yarışacağı İmam Hatip Spor Oyunları, Cemile Sultan Korusu’nda düzenlenen lansman ile tanıtıldı.&nbsp;<br><br><strong>Payitahttan Türkiye’ye yayılacak</strong></h3><p></p><p>Programa katılan Gençlik ve Spor Bakan Yardımcısı Dr. Enes Eminoğlu, Gazze’de yaşananlara değinerek başladığı konuşmasında, 2 yıldır 894 sporcunun öldürüldüğünü, 300 spor tesisinin de yerle bir edildiğini söyledi. İmam hatip nesli olarak direnişi hep hatırlayarak sahalardan, statlardan seslerini yükselttiklerini belirten Eminoğlu, “Bu duruşa destek veren sporcularımızı tebrik ediyoruz. Bizlerin de imam hatip nesli olarak bu duruş içinde olmamız lazım” dedi. İmam Hatip Spor Oyunları’nın Gençlik ve Spor Bakanlığı olarak destek verdikleri çalışmalardan biri olduğunu belirten Eminoğlu, “Bu yıl 16. kez düzenlenecek. Payitahttan yola çıkarak bütün Türkiye’ye yayılması, branşların 17’ye çıkması çok önemli. Çalışmalarımız paralel yürüyor. Sayın Cumhurbaşkanımızın da hem imam hatipli olması hem de spora değer vermesi bu alanda çok önemli” diye konuştu.</p><p></p>', '/uploads/posts/thumbnails/2025/1763392928716-690935077f0f0.jpeg', 1, 1, 14, '2025-11-17 15:22:14', '2025-11-20 09:11:27', '2025-11-18 13:42:34');
